 hi:{button:'कुकी प्रबंधन',title:'कुकी और ब्राउज़र स्टोरेज',intro:'यह प्रबंधक केवल इस साइट का स्टोरेज नियंत्रित करता है:',scope:'साइट URL',choices:'आपकी पसंद',storage:'ब्राउज़र स्टोरेज',necessary:'ज़रूरी स्टोरेज',always:'हमेशा चालू',necessaryText:'नीचे दी गई साइट सुविधाओं के लिए आवश्यक। ट्रैकिंग के लिए उपयोग नहीं होता और यहाँ बंद नहीं किया जा सकता।',theme:'थीम चयन',themeText:'लाइट, डार्क या सिस्टम थीम याद रखता है।',currency:'मुद्रा चयन',currencyText:'कीमत दिखाने के लिए चुनी गई मुद्रा याद रखता है।',market:'मार्केटप्लेस सूची और समीक्षाएँ',marketText:'इस डिवाइस पर सेवा सूची और समीक्षाएँ रखता है। ट्रैकिंग नहीं होती।',consent:'स्टोरेज पसंद',consentText:'याद रखता है कि आप वैकल्पिक स्टोरेज की अनुमति देते हैं या नहीं।',offline:'ऑफ़लाइन साइट और कैटलॉग',offlineText:'देखे गए सार्वजनिक पेज और फ़ाइलें कैश करने तथा डाउनलोड किए गए मार्गदर्शन कैटलॉग रखने की अनुमति देता है।',other:'अन्य वैकल्पिक स्टोरेज',otherText:'इस साइट के अन्य वैकल्पिक ब्राउज़र स्टोरेज की अनुमति देता है।',language:'पेज की भाषा URL से आती है; भाषा पसंद सहेजी नहीं जाती।',inventory:'पता चला स्टोरेज',refresh:'ताज़ा करें',remove:'हटाएँ',required:'ज़रूरी',empty:'इस पेज को कोई स्टोरेज आइटम नहीं दिखा।',notReadable:'पेज स्क्रिप्ट HttpOnly कुकी नहीं पढ़ सकतीं।',reject:'वैकल्पिक अस्वीकारें',save:'पसंद सहेजें',allow:'वैकल्पिक स्टोरेज की अनुमति दें',close:'बंद करें',cookie:'कुकी',local:'लोकल स्टोरेज',session:'सेशन स्टोरेज',database:'डेटाबेस',cache:'कैश फ़ाइलें',worker:'बैकग्राउंड वर्कर',saved:'आपकी पसंद सहेज दी गई है।'},
 ru:{button:'Управление cookie',title:'Cookie и хранилище браузера',intro:'Эти настройки управляют хранилищем только этого сайта:',scope:'Адрес сайта',choices:'Ваш выбор',storage:'Хранилище браузера',necessary:'Необходимое хранилище',always:'Всегда включено',necessaryText:'Нужно для указанных функций сайта. Не используется для отслеживания и не отключается здесь.',theme:'Выбор темы',themeText:'Запоминает светлую, тёмную или системную тему.',currency:'Выбор валюты',currencyText:'Запоминает валюту для отображения цен.',market:'Список услуг и отзывы',marketText:'Хранит список услуг и отзывы на устройстве. Отслеживание не ведётся.',consent:'Настройки хранилища',consentText:'Запоминает разрешение на дополнительное хранилище.',offline:'Сайт и каталоги офлайн',offlineText:'Разрешает кэшировать посещённые общедоступные страницы и файлы, а также хранить загруженные каталоги в браузере.',other:'Другие дополнительные данные',otherText:'Разрешает другие дополнительные хранилища сайта.',language:'Язык страницы определяется URL; языковые предпочтения не сохраняются.',inventory:'Обнаруженное хранилище',refresh:'Обновить',remove:'Удалить',required:'Необходимо',empty:'Страница не обнаружила элементов хранилища.',notReadable:'Скрипты страницы не могут читать HttpOnly cookie.',reject:'Отклонить дополнительное',save:'Сохранить выбор',allow:'Разрешить дополнительное хранилище',close:'Закрыть',cookie:'Cookie',local:'Локальное хранилище',session:'Хранилище сеанса',database:'База данных',cache:'Кэшированные файлы',worker:'Фоновый процесс',saved:'Ваш выбор сохранён.'},
}
const locale = computed<Locale>(() => { const page = String(lang.value || '').toLowerCase().split('-')[0]; const browser = typeof navigator === 'undefined' ? '' : navigator.language.toLowerCase().split('-')[0]; const pick = ['ar','es','zh','hi','ru'].includes(browser) ? browser : page; return (Object.hasOwn(messages, pick) ? pick : 'en') as Locale })
const t = (key: string) => messages[locale.value][key] ?? messages.en[key] ?? key
const rtl = computed(() => locale.value === 'ar')
const typeLabel = (kind: BrowserStorageEntry['kind']) => ({ cookie:'cookie', localStorage:'local', sessionStorage:'session', indexedDB:'database', cache:'cache', serviceWorker:'worker' }[kind])
function entryLabel(item: BrowserStorageEntry): string {
  if (item.descriptionKey === 'theme') return t('theme')
  if (item.descriptionKey === 'currency') return t('currency')
  if (item.descriptionKey.includes('marketplace')) return t('market')
  if (item.descriptionKey === 'offline-catalogue' || item.descriptionKey === 'pwa-offline') return t('offline')
  if (item.descriptionKey === 'consent') return t('consent')
  return t('other')
}
async function refresh() { inventory.value = await getBrowserStorageInventory() }
function loadChoices() { const saved = getStorageConsent(); choices.value = { offline: saved?.offline ?? false, other: saved?.other ?? false } }
async function open() { loadChoices(); activeTab.value = 'choices'; await refresh(); dialog.value?.showModal(); if (inventoryTimer === undefined) inventoryTimer = window.setInterval(() => { if (dialog.value?.open) void refresh() }, 4000) }
function close() { if (inventoryTimer !== undefined) window.clearInterval(inventoryTimer); inventoryTimer = undefined }
async function save(next: {offline:boolean;other:boolean}) { isSaving.value = true; try { saveStorageConsent(next); for (const category of ['offline','other'] as const) if (!next[category]) await clearOptionalStorage(category); choices.value = {...next}; await refresh(); dialog.value?.close() } finally { isSaving.value = false } }
async function remove(item: BrowserStorageEntry) { await removeBrowserStorageEntry(item); await refresh() }
function onStorage() { void refresh() }
onMounted(() => { loadChoices(); window.addEventListener('storage', onStorage); window.addEventListener('spmpst-storage-consent-change', onStorage); if (!getStorageConsent()) void open() })
onUnmounted(() => { close(); window.removeEventListener('storage', onStorage); window.removeEventListener('spmpst-storage-consent-change', onStorage) })
</script>

<template>
 <div class="cookie-manager" :dir="rtl ? 'rtl' : 'ltr'">
  <button class="cookie-manager__trigger" type="button" @click="open">{{ t('button') }}</button>
  <dialog ref="dialog" class="cookie-manager__dialog" @close="close">
   <header class="cookie-manager__header"><div><p>{{ t('button') }}</p><h2>{{ t('title') }}</h2><span>{{ t('intro') }}</span><a :href="origin" target="_blank" rel="noopener">{{ origin }}</a></div><button class="cookie-manager__close" :aria-label="t('close')" @click="dialog?.close()">×</button></header>
   <div class="cookie-manager__tabs" role="tablist" :aria-label="t('title')"><button role="tab" :aria-selected="activeTab==='choices'" @click="activeTab='choices'">{{ t('choices') }}</button><button role="tab" :aria-selected="activeTab==='storage'" @click="activeTab='storage'; refresh()">{{ t('storage') }}</button></div>
   <section v-if="activeTab==='choices'" role="tabpanel" class="cookie-manager__panel">
    <h3>{{ t('necessary') }} <span>{{ t('always') }}</span></h3><p class="cookie-manager__muted">{{ t('necessaryText') }}</p>
    <div v-for="row in [{label:'theme',text:'themeText'},{label:'currency',text:'currencyText'},{label:'market',text:'marketText'},{label:'consent',text:'consentText'}]" :key="row.label" class="cookie-manager__row"><div><strong>{{ t(row.label) }}</strong><small>{{ t(row.text) }}</small></div><input type="checkbox" checked disabled :aria-label="`${t(row.label)}: ${t('required')}`"></div>
    <label class="cookie-manager__row"><span><strong>{{ t('offline') }}</strong><small>{{ t('offlineText') }}</small></span><input v-model="choices.offline" type="checkbox" role="switch"></label>
    <label class="cookie-manager__row"><span><strong>{{ t('other') }}</strong><small>{{ t('otherText') }}</small></span><input v-model="choices.other" type="checkbox" role="switch"></label>
    <p class="cookie-manager__muted">{{ t('language') }}</p>
   </section>
   <section v-else role="tabpanel" class="cookie-manager__panel cookie-manager__inventory"><div class="cookie-manager__inventory-head"><h3>{{ t('inventory') }}</h3><button @click="refresh">{{ t('refresh') }}</button></div><p v-if="!inventory.length">{{ t('empty') }}</p><ul v-else><li v-for="item in inventory" :key="`${item.kind}:${item.internalName}`"><div><strong>{{ entryLabel(item) }}</strong><small>{{ t(typeLabel(item.kind)) }} · {{ t(item.descriptionKey==='theme'?'themeText':item.descriptionKey==='currency'?'currencyText':item.descriptionKey.includes('marketplace')?'marketText':(item.descriptionKey==='offline-catalogue'||item.descriptionKey==='pwa-offline')?'offlineText':item.descriptionKey==='consent'?'consentText':item.category==='necessary'?'necessaryText':'otherText') }}</small></div><span v-if="item.required" class="cookie-manager__badge">{{ t('required') }}</span><button v-else @click="remove(item)">{{ t('remove') }}</button></li></ul><small>{{ t('notReadable') }}</small></section>
   <footer class="cookie-manager__actions"><button @click="save({offline:false,other:false})" :disabled="isSaving">{{ t('reject') }}</button><button @click="save(choices)" :disabled="isSaving">{{ t('save') }}</button><button class="primary" @click="save({offline:true,other:true})" :disabled="isSaving">{{ t('allow') }}</button></footer>
  </dialog>
 </div>
</template>

<style scoped>
